// Родительский класс
class Animal {
  constructor(name) {
    this.name = name;  // name есть у ВСЕХ животных
  }

  eat() {
    return `${this.name} eats`;
  }
}

// Дочерний класс — наследует всё от Animal
class Dog extends Animal {
  bark() {
    return `${this.name} says Woof`;  // this.name приходит из Animal!
  }
}

const rex = new Dog("Rex");
console.log(rex.eat());   // Rex eats — метод родителя!
console.log(rex.bark());  // Rex says Woof — свой метод

class Vehicle {
  constructor(speed) {
    this.speed = speed;
  }
  move() {
    return `Moving at ${this.speed}`;
  }
}

class Car extends Vehicle {
  constructor(speed, brand) {
    super(speed);      // вызываем constructor родителя
    this.brand = brand; // добавляем своё
  }
}

class SportCar extends Car {
  constructor(brand) {
    super(300, brand);  // speed=300 по умолчанию
  }
}

const car = new SportCar("Ferrari");
console.log(car.move());  // Moving at 300
console.log(car.brand);   // Ferrari

class Employee {
  constructor(name, salary) {
    this.name = name;
    this.salary = salary;
  }
  info() {
    return `${this.name}: ${this.salary}`;
  }
}

class Manager extends Employee {
  constructor(name, salary, teamSize) {
    super(name, salary);  // 1. Сначала родитель инициализирует name, salary
    this.teamSize = teamSize;  // 2. Потом добавляем своё
  }
}

const m = new Manager("Alice", 5000, 10);
console.log(m.info());    // Alice: 5000 — метод родителя работает!
console.log(m.teamSize);  // 10 — наше поле

class Base {
  constructor(x) {
    this.x = x;
  }
}

class Bad extends Base {
  constructor(x) {
    // Забыли super(x)!
    this.x = x;  // ReferenceError: Must call super constructor
  }
}

// Правильно:
class Good extends Base {
  constructor(x, y) {
    super(x);  // Сначала super — this теперь доступен
    this.y = y;
  }
}

class Animal {
  speak() {
    return "Some sound";
  }
}

class Dog extends Animal {
  speak() {  // переопределили метод
    return "Woof";
  }
}

class Cat extends Animal {
  speak() {  // по-своему переопределили
    return "Meow";
  }
}

const animals = [new Animal(), new Dog(), new Cat()];
for (const a of animals) {
  console.log(a.speak());  // одинаковый вызов, разные результаты!
}
// Some sound
// Woof
// Meow

