class Logger {
  log(msg) {
    return `[LOG] ${msg}`;
  }
}

class TimestampLogger extends Logger {
  log(msg) {
    const base = super.log(msg);  // вызываем родительский log
    return `${new Date().getFullYear()} ${base}`;  // добавляем год
  }
}

const l = new TimestampLogger();
console.log(l.log("hello"));  // 2026 [LOG] hello — расширили, не заменили

