class A {
  a() { return "a"; }
}
class B extends A {
  b() { return "b"; }
}
class C extends B {
  c() { return "c"; }
}

const obj = new C();
console.log(obj.a());  // "a" — нашёл в дедушке A
console.log(obj.b());  // "b" — нашёл в папе B
console.log(obj.c());  // "c" — в самом C

// Все три метода доступны в C!

// Расширяем встроенный Array
class NumberArray extends Array {
  sum() {
    return this.reduce((acc, n) => acc + n, 0);
  }
}

const nums = new NumberArray(1, 2, 3, 4);
console.log(nums.length);  // 4 — все методы Array работают!
console.log(nums.sum());   // 10 — наш метод
console.log(nums.push(5)); // работает push из Array

class Employee {}
class Manager extends Employee {}

const m = new Manager();
console.log(m instanceof Manager);  // true
console.log(m instanceof Employee); // true — Manager есть Employee
console.log(m instanceof Object);   // true — все объекты наследуют Object

class Animal {
  speak() { return "..."; }
}
class Dog extends Animal {
  speak() { return "Woof"; }
}
class Cat extends Animal {
  speak() { return "Meow"; }
}
class Fish extends Animal {
  speak() { return "Blub"; }  // новый класс — старый код не меняем
}

function describe(animal) {
  return `It says: ${animal.speak()}`;  // работает с ЛЮБЫМ Animal
}

console.log(describe(new Dog()));   // It says: Woof
console.log(describe(new Fish()));  // It says: Blub

